$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

Write-Host ""
Write-Host "=============================================" -ForegroundColor Cyan
Write-Host " SaborFlow - Hotfix Etapa 13.6" -ForegroundColor Cyan
Write-Host " Call sites de sessao persistente" -ForegroundColor Cyan
Write-Host "=============================================" -ForegroundColor Cyan
Write-Host ""

if (-not (Test-Path ".\package.json")) {
    throw "Execute este hotfix na pasta raiz do projeto SaborFlow."
}

if (-not (Test-Path ".\lib\security\admin-sessions.ts")) {
    throw "Etapa 13.6 base nao encontrada. Nada foi alterado."
}

if (-not (Select-String -Path ".\lib\auth.ts" -Pattern 'return `v4.${encoded}.${sign(encoded)}`' -SimpleMatch -Quiet)) {
    throw "lib\auth.ts nao esta na versao v4 esperada da Etapa 13.6. Nada foi alterado."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $env:TEMP "SaborFlow-Hotfix13-6-Backup-$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$targets = @(
    "lib\security\admin-sessions.ts"
    "database\migrations\032_admin_sessions_devices.sql"
    "components\admin\security-panel.tsx"
    "app\api\admin\organizations\route.ts"
    "app\api\admin\switch-organization\route.ts"
    "app\api\demo\public\start\route.ts"
    "app\api\demo\trial\start\route.ts"
)

foreach ($target in $targets) {
    if (Test-Path $target) {
        $dest = Join-Path $backupRoot $target
        $destDir = Split-Path -Parent $dest
        if ($destDir) {
            New-Item -ItemType Directory -Force -Path $destDir | Out-Null
        }
        Copy-Item -LiteralPath $target -Destination $dest -Force
    }
}

$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

function Write-Utf8Base64File {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Base64
    )

    $directory = Split-Path -Parent $Path
    if ($directory) {
        New-Item -ItemType Directory -Force -Path $directory | Out-Null
    }

    $bytes = [System.Convert]::FromBase64String($Base64)
    $content = [System.Text.Encoding]::UTF8.GetString($bytes)
    $fullPath = [System.IO.Path]::GetFullPath((Join-Path (Get-Location) $Path))
    [System.IO.File]::WriteAllText($fullPath, $content, $utf8NoBom)
    Write-Host "Corrigido: $Path" -ForegroundColor Green
}

Write-Utf8Base64File -Path "lib\security\admin-sessions.ts" -Base64 ""
Write-Utf8Base64File -Path "database\migrations\032_admin_sessions_devices.sql" -Base64 ""
Write-Utf8Base64File -Path "components\admin\security-panel.tsx" -Base64 ""
Write-Utf8Base64File -Path "app\api\admin\organizations\route.ts" -Base64 ""
Write-Utf8Base64File -Path "app\api\admin\switch-organization\route.ts" -Base64 ""
Write-Utf8Base64File -Path "app\api\demo\public\start\route.ts" -Base64 ""
Write-Utf8Base64File -Path "app\api\demo\trial\start\route.ts" -Base64 ""

Write-Host ""
Write-Host "Verificando alteracoes..." -ForegroundColor Cyan
git diff --check
if ($LASTEXITCODE -ne 0) {
    throw "git diff --check encontrou um problema. Backup: $backupRoot"
}

Write-Host ""
Write-Host "Executando build..." -ForegroundColor Cyan
npm.cmd run build
if ($LASTEXITCODE -ne 0) {
    throw "O build ainda encontrou erro. NAO execute a Migration 032. Backup: $backupRoot"
}

Write-Host ""
Write-Host "HOTFIX 13.6 OK - BUILD APROVADO." -ForegroundColor Green
Write-Host "A Migration 032 continua NAO executada." -ForegroundColor Yellow
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
Write-Host ""
git status --short
